1	/*
2	 * Tests for useCartDrawer.ts — the shared cart-drawer open/close state, its Context wiring, and
3	 * the CartDrawerProvider that renders CartDrawerContainer alongside it (see that file's own
4	 * module docblock for the "structural trap" this exists to avoid).
5	 *
6	 * CartDrawerContainer itself (a real page-level container pulling in useCurrentBasket,
7	 * useProducts, useWishList, useWishlistAuthDrawer, etc.) is mocked at the smallest surface per
8	 * testing.md — its own contract has its own suite. This file asserts only useCartDrawer.ts's own
9	 * contract: state transitions, trigger-ref capture, the route-change auto-close effect, and that
10	 * CartDrawerProvider always renders the real container (not just the Provider, mirroring the
11	 * AddToCartModalProvider gap this file exists to avoid).
12	 */
13	import React from 'react';
14	import { describe, test, expect, vi, beforeEach } from 'vitest';
15	import { render, screen, act } from '@testing-library/react';
16	
17	let mockPathname = '/product/test';
18	vi.mock('react-router-dom', () => ({
19	  useLocation: () => ({ pathname: mockPathname }),
20	}));
21	
22	const cartDrawerContainerSpy = vi.fn();
23	vi.mock('app/pages/cart/cartDrawerContainer', () => ({
24	  CartDrawerContainer: (props: { isOpen: boolean; onClose: () => void; finalFocusRef?: unknown }) => {
25	    cartDrawerContainerSpy(props);
26	    return <div data-testid="cart-drawer-container-stub" data-is-open={String(props.isOpen)} />;
27	  },
28	}));
29	
30	import { CartDrawerProvider, useCartDrawer, useCartDrawerState } from './useCartDrawer';
31	
32	/** Exercises useCartDrawerState() directly and exposes its return value for assertions. */
33	function StateProbe({ onState }: { onState: (state: ReturnType<typeof useCartDrawerState>) => void }) {
34	  const state = useCartDrawerState();
35	  onState(state);
36	  return null;
37	}
38	
39	/** Exercises useCartDrawer()'s Context read from inside a real CartDrawerProvider subtree. */
40	function ContextProbe({ onState }: { onState: (state: ReturnType<typeof useCartDrawer>) => void }) {
41	  const state = useCartDrawer();
42	  onState(state);
43	  return null;
44	}
45	
46	describe('useCartDrawerState', () => {
47	  beforeEach(() => {
48	    mockPathname = '/product/test';
49	    cartDrawerContainerSpy.mockClear();
50	  });
51	
52	  test('starts closed', () => {
53	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
54	    render(<StateProbe onState={(s) => (latest = s)} />);
55	    expect(latest?.isOpen).toBe(false);
56	  });
57	
58	  test('onOpen sets isOpen to true', () => {
59	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
60	    render(<StateProbe onState={(s) => (latest = s)} />);
61	
62	    act(() => latest?.onOpen());
63	
64	    expect(latest?.isOpen).toBe(true);
65	  });
66	
67	  test('onOpen(trigger) captures the passed element as triggerRef.current — one real trigger origin', () => {
68	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
69	    render(<StateProbe onState={(s) => (latest = s)} />);
70	    const headerBagIcon = document.createElement('button');
71	    headerBagIcon.setAttribute('data-origin', 'header-bag-icon');
72	
73	    act(() => latest?.onOpen(headerBagIcon));
74	
75	    expect(latest?.triggerRef.current).toBe(headerBagIcon);
76	  });
77	
78	  test('a second onOpen(trigger) from a different origin overwrites triggerRef.current — the second real trigger origin', () => {
79	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
80	    render(<StateProbe onState={(s) => (latest = s)} />);
81	    const headerBagIcon = document.createElement('button');
82	    const pdpAddToBagButton = document.createElement('button');
83	    pdpAddToBagButton.setAttribute('data-origin', 'pdp-add-to-bag');
84	
85	    act(() => latest?.onOpen(headerBagIcon));
86	    expect(latest?.triggerRef.current).toBe(headerBagIcon);
87	
88	    act(() => latest?.onClose());
89	    act(() => latest?.onOpen(pdpAddToBagButton));
90	
91	    expect(latest?.triggerRef.current).toBe(pdpAddToBagButton);
92	  });
93	
94	  test('onOpen() with no trigger leaves a previously-captured triggerRef untouched, not cleared', () => {
95	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
96	    render(<StateProbe onState={(s) => (latest = s)} />);
97	    const trigger = document.createElement('button');
98	
99	    act(() => latest?.onOpen(trigger));
100	    act(() => latest?.onClose());
101	    act(() => latest?.onOpen());
102	
103	    expect(latest?.triggerRef.current).toBe(trigger);
104	  });
105	
106	  test('onOpen(null) also leaves a previously-captured triggerRef untouched', () => {
107	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
108	    render(<StateProbe onState={(s) => (latest = s)} />);
109	    const trigger = document.createElement('button');
110	
111	    act(() => latest?.onOpen(trigger));
112	    act(() => latest?.onClose());
113	    act(() => latest?.onOpen(null));
114	
115	    expect(latest?.triggerRef.current).toBe(trigger);
116	  });
117	
118	  test('onClose sets isOpen to false', () => {
119	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
120	    render(<StateProbe onState={(s) => (latest = s)} />);
121	
122	    act(() => latest?.onOpen());
123	    expect(latest?.isOpen).toBe(true);
124	
125	    act(() => latest?.onClose());
126	    expect(latest?.isOpen).toBe(false);
127	  });
128	
129	  test("closes when the route changes while open — mirrors use-add-to-cart-modal.js's own [pathname] effect", () => {
130	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
131	    const { rerender } = render(<StateProbe onState={(s) => (latest = s)} />);
132	
133	    act(() => latest?.onOpen());
134	    expect(latest?.isOpen).toBe(true);
135	
136	    // Simulate navigation — e.g. clicking a product image/name link inside the cart drawer, or
137	    // ZimmCartButtonGroup's Checkout button navigating to /checkout.
138	    mockPathname = '/checkout';
139	    rerender(<StateProbe onState={(s) => (latest = s)} />);
140	
141	    expect(latest?.isOpen).toBe(false);
142	  });
143	
144	  test('does not affect an already-closed drawer on route change', () => {
145	    let latest: ReturnType<typeof useCartDrawerState> | undefined;
146	    const { rerender } = render(<StateProbe onState={(s) => (latest = s)} />);
147	
148	    expect(latest?.isOpen).toBe(false);
149	    mockPathname = '/checkout';
150	    rerender(<StateProbe onState={(s) => (latest = s)} />);
151	
152	    expect(latest?.isOpen).toBe(false);
153	  });
154	});
155	
156	describe('useCartDrawer (Context read)', () => {
157	  // Degrades to a stable no-op outside a Provider (matching useUiCopy.ts's own
158	  // `useContext(...) ?? FALLBACK_ONLY` shape) rather than throwing — confirmed necessary, not
159	  // just convenient: product-view/index.stories.tsx (unmodified by this step) wraps ProductView
160	  // in the now-removed AddToCartModalProvider, with no CartDrawerProvider in its own decorator
161	  // stack, and every one of its stories renders the real default ProductView export. See
162	  // useCartDrawer.ts's own doc on useCartDrawer for the live-Storybook verification.
163	  test('does not throw outside a CartDrawerProvider — renders isOpen: false', () => {
164	    let latest: ReturnType<typeof useCartDrawer> | undefined;
165	    expect(() => render(<ContextProbe onState={(s) => (latest = s)} />)).not.toThrow();
166	    expect(latest?.isOpen).toBe(false);
167	  });
168	
169	  test('onOpen() outside a Provider is a harmless no-op — does not throw when clicked', () => {
170	    let latest: ReturnType<typeof useCartDrawer> | undefined;
171	    render(<ContextProbe onState={(s) => (latest = s)} />);
172	    expect(() => latest?.onOpen(document.createElement('button'))).not.toThrow();
173	  });
174	
175	  test('onClose() outside a Provider is a harmless no-op', () => {
176	    let latest: ReturnType<typeof useCartDrawer> | undefined;
177	    render(<ContextProbe onState={(s) => (latest = s)} />);
178	    expect(() => latest?.onClose()).not.toThrow();
179	  });
180	});
181	
182	describe('CartDrawerProvider', () => {
183	  beforeEach(() => {
184	    cartDrawerContainerSpy.mockClear();
185	  });
186	
187	  const buildValue = (overrides: Partial<ReturnType<typeof useCartDrawerState>> = {}) => ({
188	    isOpen: false,
189	    onOpen: vi.fn(),
190	    onClose: vi.fn(),
191	    triggerRef: { current: null } as React.RefObject<HTMLElement>,
192	    ...overrides,
193	  });
194	
195	  test('always renders CartDrawerContainer alongside children — the AddToCartModalProvider gap this exists to avoid', () => {
196	    const value = buildValue();
197	    render(
198	      <CartDrawerProvider value={value}>
199	        <div data-testid="page-content" />
200	      </CartDrawerProvider>,
201	    );
202	
203	    expect(screen.getByTestId('page-content')).toBeInTheDocument();
204	    // The real assertion: CartDrawerContainer was actually rendered, not merely available via
205	    // Context for some other component to maybe render later (the exact gap AddToCartModal
206	    // shipped with — a Provider mounted with nothing ever consuming it to render real UI).
207	    expect(cartDrawerContainerSpy).toHaveBeenCalledWith(
208	      expect.objectContaining({ isOpen: false, onClose: value.onClose, finalFocusRef: value.triggerRef }),
209	    );
210	  });
211	
212	  test('forwards value.isOpen/onClose/triggerRef to CartDrawerContainer verbatim', () => {
213	    const value = buildValue({ isOpen: true });
214	    render(
215	      <CartDrawerProvider value={value}>
216	        <div />
217	      </CartDrawerProvider>,
218	    );
219	
