/*
 * Tests for useCartDrawer.ts — the shared cart-drawer open/close state, its Context wiring, and
 * the CartDrawerProvider that renders CartDrawerContainer alongside it (see that file's own
 * module docblock for the "structural trap" this exists to avoid).
 *
 * CartDrawerContainer itself (a real page-level container pulling in useCurrentBasket,
 * useProducts, useWishList, useWishlistAuthDrawer, etc.) is mocked at the smallest surface per
 * testing.md — its own contract has its own suite. This file asserts only useCartDrawer.ts's own
 * contract: state transitions, trigger-ref capture, the route-change auto-close effect, and that
 * CartDrawerProvider always renders the real container (not just the Provider, mirroring the
 * AddToCartModalProvider gap this file exists to avoid).
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, act } from '@testing-library/react';

let mockPathname = '/product/test';
vi.mock('react-router-dom', () => ({
  useLocation: () => ({ pathname: mockPathname }),
}));

const cartDrawerContainerSpy = vi.fn();
vi.mock('app/pages/cart/cartDrawerContainer', () => ({
  CartDrawerContainer: (props: { isOpen: boolean; onClose: () => void; finalFocusRef?: unknown }) => {
    cartDrawerContainerSpy(props);
    return <div data-testid="cart-drawer-container-stub" data-is-open={String(props.isOpen)} />;
  },
}));

import { CartDrawerProvider, useCartDrawer, useCartDrawerState } from './useCartDrawer';

/** Exercises useCartDrawerState() directly and exposes its return value for assertions. */
function StateProbe({ onState }: { onState: (state: ReturnType<typeof useCartDrawerState>) => void }) {
  const state = useCartDrawerState();
  onState(state);
  return null;
}

/** Exercises useCartDrawer()'s Context read from inside a real CartDrawerProvider subtree. */
function ContextProbe({ onState }: { onState: (state: ReturnType<typeof useCartDrawer>) => void }) {
  const state = useCartDrawer();
  onState(state);
  return null;
}

describe('useCartDrawerState', () => {
  beforeEach(() => {
    mockPathname = '/product/test';
    cartDrawerContainerSpy.mockClear();
  });

  test('starts closed', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);
    expect(latest?.isOpen).toBe(false);
  });

  test('onOpen sets isOpen to true', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);

    act(() => latest?.onOpen());

    expect(latest?.isOpen).toBe(true);
  });

  test('onOpen(trigger) captures the passed element as triggerRef.current — one real trigger origin', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);
    const headerBagIcon = document.createElement('button');
    headerBagIcon.setAttribute('data-origin', 'header-bag-icon');

    act(() => latest?.onOpen(headerBagIcon));

    expect(latest?.triggerRef.current).toBe(headerBagIcon);
  });

  test('a second onOpen(trigger) from a different origin overwrites triggerRef.current — the second real trigger origin', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);
    const headerBagIcon = document.createElement('button');
    const pdpAddToBagButton = document.createElement('button');
    pdpAddToBagButton.setAttribute('data-origin', 'pdp-add-to-bag');

    act(() => latest?.onOpen(headerBagIcon));
    expect(latest?.triggerRef.current).toBe(headerBagIcon);

    act(() => latest?.onClose());
    act(() => latest?.onOpen(pdpAddToBagButton));

    expect(latest?.triggerRef.current).toBe(pdpAddToBagButton);
  });

  test('onOpen() with no trigger leaves a previously-captured triggerRef untouched, not cleared', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);
    const trigger = document.createElement('button');

    act(() => latest?.onOpen(trigger));
    act(() => latest?.onClose());
    act(() => latest?.onOpen());

    expect(latest?.triggerRef.current).toBe(trigger);
  });

  test('onOpen(null) also leaves a previously-captured triggerRef untouched', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);
    const trigger = document.createElement('button');

    act(() => latest?.onOpen(trigger));
    act(() => latest?.onClose());
    act(() => latest?.onOpen(null));

    expect(latest?.triggerRef.current).toBe(trigger);
  });

  test('onClose sets isOpen to false', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    render(<StateProbe onState={(s) => (latest = s)} />);

    act(() => latest?.onOpen());
    expect(latest?.isOpen).toBe(true);

    act(() => latest?.onClose());
    expect(latest?.isOpen).toBe(false);
  });

  test("closes when the route changes while open — mirrors use-add-to-cart-modal.js's own [pathname] effect", () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    const { rerender } = render(<StateProbe onState={(s) => (latest = s)} />);

    act(() => latest?.onOpen());
    expect(latest?.isOpen).toBe(true);

    // Simulate navigation — e.g. clicking a product image/name link inside the cart drawer, or
    // ZimmCartButtonGroup's Checkout button navigating to /checkout.
    mockPathname = '/checkout';
    rerender(<StateProbe onState={(s) => (latest = s)} />);

    expect(latest?.isOpen).toBe(false);
  });

  test('does not affect an already-closed drawer on route change', () => {
    let latest: ReturnType<typeof useCartDrawerState> | undefined;
    const { rerender } = render(<StateProbe onState={(s) => (latest = s)} />);

    expect(latest?.isOpen).toBe(false);
    mockPathname = '/checkout';
    rerender(<StateProbe onState={(s) => (latest = s)} />);

    expect(latest?.isOpen).toBe(false);
  });
});

describe('useCartDrawer (Context read)', () => {
  // Degrades to a stable no-op outside a Provider (matching useUiCopy.ts's own
  // `useContext(...) ?? FALLBACK_ONLY` shape) rather than throwing — confirmed necessary, not
  // just convenient: product-view/index.stories.tsx (unmodified by this step) wraps ProductView
  // in the now-removed AddToCartModalProvider, with no CartDrawerProvider in its own decorator
  // stack, and every one of its stories renders the real default ProductView export. See
  // useCartDrawer.ts's own doc on useCartDrawer for the live-Storybook verification.
  test('does not throw outside a CartDrawerProvider — renders isOpen: false', () => {
    let latest: ReturnType<typeof useCartDrawer> | undefined;
    expect(() => render(<ContextProbe onState={(s) => (latest = s)} />)).not.toThrow();
    expect(latest?.isOpen).toBe(false);
  });

  test('onOpen() outside a Provider is a harmless no-op — does not throw when clicked', () => {
    let latest: ReturnType<typeof useCartDrawer> | undefined;
    render(<ContextProbe onState={(s) => (latest = s)} />);
    expect(() => latest?.onOpen(document.createElement('button'))).not.toThrow();
  });

  test('onClose() outside a Provider is a harmless no-op', () => {
    let latest: ReturnType<typeof useCartDrawer> | undefined;
    render(<ContextProbe onState={(s) => (latest = s)} />);
    expect(() => latest?.onClose()).not.toThrow();
  });
});

describe('CartDrawerProvider', () => {
  beforeEach(() => {
    cartDrawerContainerSpy.mockClear();
  });

  const buildValue = (overrides: Partial<ReturnType<typeof useCartDrawerState>> = {}) => ({
    isOpen: false,
    onOpen: vi.fn(),
    onClose: vi.fn(),
    triggerRef: { current: null } as React.RefObject<HTMLElement>,
    ...overrides,
  });

  test('always renders CartDrawerContainer alongside children — the AddToCartModalProvider gap this exists to avoid', () => {
    const value = buildValue();
    render(
      <CartDrawerProvider value={value}>
        <div data-testid="page-content" />
      </CartDrawerProvider>,
    );

    expect(screen.getByTestId('page-content')).toBeInTheDocument();
    // The real assertion: CartDrawerContainer was actually rendered, not merely available via
    // Context for some other component to maybe render later (the exact gap AddToCartModal
    // shipped with — a Provider mounted with nothing ever consuming it to render real UI).
    expect(cartDrawerContainerSpy).toHaveBeenCalledWith(
      expect.objectContaining({ isOpen: false, onClose: value.onClose, finalFocusRef: value.triggerRef }),
    );
  });

  test('forwards value.isOpen/onClose/triggerRef to CartDrawerContainer verbatim', () => {
    const value = buildValue({ isOpen: true });
    render(
      <CartDrawerProvider value={value}>
        <div />
      </CartDrawerProvider>,
    );

    expect(screen.getByTestId('cart-drawer-container-stub')).toHaveAttribute('data-is-open', 'true');
  });

  test('a nested consumer reads the exact same value via useCartDrawer() — one shared instance, not a second copy', () => {
    const value = buildValue({ isOpen: true });
    let readByChild: ReturnType<typeof useCartDrawer> | undefined;

    render(
      <CartDrawerProvider value={value}>
        <ContextProbe onState={(s) => (readByChild = s)} />
      </CartDrawerProvider>,
    );

    expect(readByChild).toBe(value);
  });
});

